console.log(out.join('\n'));
","solution":"function makeCounter(start, step) {
  let count = start;
  return {
    inc() { count += step; },
    dec() { count -= step; },
    reset() { count = start; },
    get() { return count; }
  };
}

const counters = new Map();
const out = [];
for (const raw of stdin.split('\n')) {
  const line = raw.trim();
  if (!line) continue;
  const [cmd, name, a, b] = line.split(' ').filter(Boolean);
  if (cmd === 'create') {
    counters.set(name, makeCounter(Number(a), Number(b)));
    continue;
  }
  const counter = counters.get(name);
  if (!counter) {
    out.push('error: unknown counter ' + name);
    continue;
  }
  if (cmd === 'get') out.push(name + '=' + counter.get());
  else counter[cmd]();
}
console.log(out.join('\n'));
","explanation":["makeCounter declares count with let; the four returned methods close over count, start and step.","Each call to makeCounter creates a new environment, so counters a and b never share state.","A Map stores the counter objects by name; creating the same name again replaces the old closure.","For every other command, look up the counter, print an error if missing, otherwise call the method or print the value."],"tests":[{"input":"create a 5 1
inc a
