","output":"puppy.speak = woof (from dog)
puppy.legs = 4 (from animal)
puppy.fly = undefined
puppy.speak = yip (own)
dog.speak = woof (own)"},"constraints":["Names, keys and values contain no spaces or '=' characters other than the separator.","Values are stored as strings.","Objects created with parent null must not inherit anything (not even toString)."],"starter":"const objects = new Map();
const names = new Map(); // object -> name
const out = [];

