console.log(out.join('\n'));
","solution":"const objects = new Map();
const names = new Map();
const out = [];

function ownerOf(obj, key) {
  let current = obj;
  while (current !== null) {
    if (Object.prototype.hasOwnProperty.call(current, key)) return current;
    current = Object.getPrototypeOf(current);
  }
  return null;
}

for (const raw of stdin.split('\n')) {
  const parts = raw.trim().split(' ').filter(Boolean);
  if (!parts.length) continue;
  const cmd = parts[0];
  if (cmd === 'obj') {
    const [, name, parentName, ...props] = parts;
    const parent = parentName === 'null' ? null : objects.get(parentName);
    const obj = Object.create(parent);
    for (const p of props) {
      const [k, v] = p.split('=');
      obj[k] = v;
    }
    objects.set(name, obj);
    names.set(obj, name);
  } else if (cmd === 'set') {
    const [k, v] = parts[2].split('=');
    objects.get(parts[1])[k] = v;
  } else if (cmd === 'get') {
    const name = parts[1];
    const key = parts[2];
    const obj = objects.get(name);
    const owner = ownerOf(obj, key);
    if (!owner) out.push(`${name}.${key} = undefined`);
    else if (owner === obj) out.push(`${name}.${key} = ${obj[key]} (own)`);
    else out.push(`${name}.${key} = ${obj[key]} (from ${names.get(owner)})`);
  }
}
console.log(out.join('\n'));
","explanation":["Object.create(parent) sets the new object's prototype; Object.create(null) gives an object with no prototype at all.","Own properties are assigned directly, so later assignments shadow inherited values instead of changing the parent.","ownerOf checks own properties with Object.prototype.hasOwnProperty.call (safe even for null-prototype objects), then moves up with Object.getPrototypeOf.","obj[key] performs the engine's own lookup; ownerOf only identifies which object supplied the value."],"tests":[{"input":"obj animal null speak=generic legs=4
