Host: api.example.com
Connection: close
Body length: 15"},{"input":"GET / HTTP/1.0

","output":"Method: GET
Path: /
Query: (none)
Host: (missing)
Connection: close
Body length: 0"},{"input":"get /files?name=my%20notes.pdf&download HTTP/1.1
host: cdn.example.com
connection: Keep-Alive

","output":"Method: GET
